(async()=>{
'use strict';const $=id=>document.getElementById(id),C=GameCore;let puzzle;
try{if(location.hash){const text=decodeURIComponent(location.hash.slice(1));if(text.length>12000)throw new Error();puzzle=C.validatePuzzle(JSON.parse(text));}else{const id=new URLSearchParams(location.search).get('edition');if(id&&!/^\d{4}-\d{2}-\d{2}-[a-f0-9]{1,8}$/.test(id))throw new Error();const r=await fetch(id?`editions/${id}.json`:'editions/sample.json');if(!r.ok)throw new Error();puzzle=C.validatePuzzle(await r.json());}}
catch{$('loadError').hidden=false;$('loadError').textContent='This edition couldn’t load. Check your link or ask the newsletter editor for a new one.';document.querySelector('nav').hidden=true;$('fivePanel').hidden=true;return;}
$('editionTitle').textContent=puzzle.title;$('editionDate').textContent=puzzle.date;document.title=puzzle.title;
const key='weekly-games-'+puzzle.id;let state={guesses:[],solved:[],mistakes:0,history:[]},selected=[],order=C.shuffle(puzzle.groups.flatMap(g=>g.words),puzzle.id);
try{const old=JSON.parse(localStorage.getItem(key));if(old){if(!Array.isArray(old.guesses)||old.guesses.length>6||old.guesses.some(g=>typeof g!=='string'||!/^[A-Z]{5}$/.test(g))||!Array.isArray(old.history)||old.history.length>8)throw new Error();state.guesses=[];for(const g of old.guesses){if(state.guesses.includes(puzzle.word))break;state.guesses.push(g);}for(const selection of old.history){if(state.mistakes>=4||state.solved.length===4)break;const result=C.evaluateGroup(puzzle,selection);if(selection.some(w=>state.solved.some(i=>puzzle.groups[i].words.includes(w))))throw new Error();state.history.push(selection);if(result.match>=0)state.solved.push(result.match);else state.mistakes++;}}}catch{state={guesses:[],solved:[],mistakes:0,history:[]};}
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{$('saveNote').textContent='Progress could not be saved in this browser. Keep this tab open to finish.';}}
function wordFinished(){return state.guesses.includes(puzzle.word)||state.guesses.length===6;}
function renderWord(){const board=$('wordBoard');board.replaceChildren();const letters={};for(let row=0;row<6;row++){const el=document.createElement('div');el.className='guess-row';const guess=state.guesses[row]||'',scores=guess?C.scoreGuess(guess,puzzle.word):[];for(let i=0;i<5;i++){const tile=document.createElement('div');tile.className='tile '+(scores[i]||'');tile.textContent=guess[i]||'';tile.setAttribute('aria-label',guess[i]?`${guess[i]}: ${scores[i]==='correct'?'correct position':scores[i]==='present'?'in the word, different position':'not in the word'}`:'Empty letter');el.append(tile);if(guess[i]){const rank={absent:1,present:2,correct:3};if((rank[scores[i]]||0)>(rank[letters[guess[i]]]||0))letters[guess[i]]=scores[i];}}board.append(el);}
const done=wordFinished();$('guessInput').disabled=done;$('guessButton').disabled=done;$('shareWord').hidden=!done;$('wordStatus').textContent=state.guesses.includes(puzzle.word)?`Got it in ${state.guesses.length}!`:done?`The word was ${puzzle.word}. See you next edition.`:`${6-state.guesses.length} guesses left.`;$('keyboard').replaceChildren();for(const text of ['QWERTYUIOP','ASDFGHJKL','ZXCVBNM']){const row=document.createElement('div');row.className='key-row';const chars=text==='ZXCVBNM'?['Enter',...text,'⌫']:[...text];for(const char of chars){const b=document.createElement('button');b.type='button';b.className='key '+(letters[char]||'')+(['Enter','⌫'].includes(char)?' wide':'');b.textContent=char;b.disabled=done;b.setAttribute('aria-label',char==='⌫'?'Backspace':`${char}${letters[char]?' '+letters[char]:''}`);b.addEventListener('click',()=>{if(char==='Enter')submitWord();else if(char==='⌫')$('guessInput').value=$('guessInput').value.slice(0,-1);else if($('guessInput').value.length<5)$('guessInput').value+=char;});row.append(b);}$('keyboard').append(row);}}
function submitWord(){if(wordFinished())return;const guess=$('guessInput').value.trim().toUpperCase();if(!/^[A-Z]{5}$/.test(guess)){$('wordStatus').textContent='Enter exactly five letters.';return;}if(state.guesses.includes(guess)){$('wordStatus').textContent='You already tried that word.';return;}state.guesses.push(guess);$('guessInput').value='';save();renderWord();}
$('guessForm').addEventListener('submit',e=>{e.preventDefault();submitWord();});$('guessInput').addEventListener('input',()=>{$('guessInput').value=$('guessInput').value.replace(/[^a-z]/gi,'').toUpperCase().slice(0,5);});$('hintButton').addEventListener('click',()=>{$('wordHint').hidden=false;$('wordHint').textContent=puzzle.hint||'No hint for this edition.';});
function connectionsFinished(){return state.solved.length===4||state.mistakes===4;}
function renderConnections(message){const done=connectionsFinished();$('solvedGroups').replaceChildren();const shown=state.mistakes===4?[...state.solved,...[0,1,2,3].filter(i=>!state.solved.includes(i))]:state.solved;for(const i of shown){const el=document.createElement('div');el.className='group group-'+i;const title=document.createElement('strong');title.textContent=puzzle.groups[i].name;el.append(title,document.createTextNode(puzzle.groups[i].words.join(' · ')));$('solvedGroups').append(el);}$('connectionBoard').replaceChildren();if(!done)for(const word of order.filter(w=>!state.solved.some(i=>puzzle.groups[i].words.includes(w)))){const b=document.createElement('button');b.className='word-button';b.textContent=word;b.setAttribute('aria-pressed',String(selected.includes(word)));b.addEventListener('click',()=>{if(selected.includes(word))selected=selected.filter(w=>w!==word);else if(selected.length<4)selected.push(word);renderConnections();});$('connectionBoard').append(b);}$('submitGroup').disabled=done||selected.length!==4;$('shuffle').disabled=done;$('deselect').disabled=done;$('shareConnections').hidden=!done;$('mistakes').textContent=`${4-state.mistakes} mistakes remaining`;$('connectionStatus').textContent=message||(state.solved.length===4?'All four groups found. Nicely done.':done?'Here are the groups. Try the next edition.':`${selected.length} of 4 words selected.`);}
$('submitGroup').addEventListener('click',()=>{if(connectionsFinished()||selected.length!==4)return;const selection=[...selected];if(state.history.some(p=>[...p].sort().join('|')===[...selection].sort().join('|'))){renderConnections('You already tried that group. Try a different combination.');return;}const result=C.evaluateGroup(puzzle,selection);state.history.push(selection);let message;if(result.match>=0){state.solved.push(result.match);selected=[];message='Found a group!';}else{state.mistakes++;message=result.near?'One away. Three of those belong together.':'Not a group. Try a different connection.';if(connectionsFinished())selected=[];}save();renderConnections(connectionsFinished()?undefined:message);});$('shuffle').addEventListener('click',()=>{order=C.shuffle(order,String(Date.now()));renderConnections();});$('deselect').addEventListener('click',()=>{selected=[];renderConnections();});
function tab(five){$('fivePanel').hidden=!five;$('connectionsPanel').hidden=five;$('fiveTab').setAttribute('aria-pressed',String(five));$('connectionsTab').setAttribute('aria-pressed',String(!five));}$('fiveTab').addEventListener('click',()=>tab(true));$('connectionsTab').addEventListener('click',()=>tab(false));
async function share(text,button){try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(text);else{const field=document.createElement('textarea');field.value=text;field.style.cssText='position:fixed;left:-9999px';document.body.append(field);try{field.select();if(!document.execCommand('copy'))throw new Error('Copy failed');}finally{field.remove();}}button.textContent='Copied!';}catch{button.textContent='Copy unavailable in this browser.';}}
$('shareWord').addEventListener('click',()=>share(`Weekly Wins · Five letters · ${puzzle.date}\n${state.guesses.includes(puzzle.word)?state.guesses.length:'X'}/6\n${state.guesses.map(g=>C.scoreGuess(g,puzzle.word).map(s=>({correct:'🟩',present:'🟨',absent:'⬛'}[s])).join('')).join('\n')}`,$('shareWord')));
$('shareConnections').addEventListener('click',()=>share(`Weekly Wins · Connections · ${puzzle.date}\n${state.history.map(s=>s.map(w=>['🟨','🟩','🟦','🟪'][puzzle.groups.findIndex(g=>g.words.includes(w))]).join('')).join('\n')}`,$('shareConnections')));renderWord();renderConnections();
})();
